/*
 * DIR_$SERVER - Directory half of the remote-file server
 *
 * Original address: 0x00E58200 (SAU2 map: DIR_$SERVER)
 * Size: 414 bytes (0x00E58200 .. 0x00E5839D); its zero count word follows
 * at 0x00E5839E.
 * Generated by: Claude Opus 5.5
 *
 * REM_FILE_$SERVER hands it requests with opcodes 0x2A..0x5C (0x00E63936).
 * It checks the request's header and body versions, runs the operation
 * through DIR_$DO_OP with the requester's SIDs and project list in force
 * (and optionally one subsystem level up and with auditing suspended),
 * then restores the server's own identity.
 *
 * Frame (link.w A6,-0x8; D2/A2-A5 saved; A5 = 0xE801E4, DIR_SERVER):
 *   (0x08,A6) request (A2)   (0x0C,A6) reply (A3)   (0x10,A6) reply_len (D2)
 *   (-0x04,A6) scratch status for the identity save/restore
 *
 * Blocks:
 *   0x00E5821A-0x00E58226  reply +0x08 = 0, *reply_len = 0x14, reply +0x12 = 0
 *   0x00E58228-0x00E58244  header version > 1: reply version 1, "bad
 *                          request header version"
 *   0x00E58248-0x00E5826E  body version above DIR_$OP_REC(op >> 1).version:
 *                          reply that version, "bad request body version"
 *   0x00E58272-0x00E58282  header version 0: the default project record
 *   0x00E58284-0x00E582A8  first time: save the server's own SIDs
 *   0x00E582AC-0x00E582F6  ACL_$ENTER_SUPER, AUDIT_$SUSPEND, take on the
 *                          requester's SIDs and project list (each failure
 *                          skips to the restore)
 *   0x00E582F8-0x00E58350  optional ACL_$UP, AUDIT_$RESUME unless bit 0,
 *                          ACL_$EXIT_SUPER; DIR_$DO_OP(request, 0x292, 0x11A,
 *                          reply, reply_len); ACL_$ENTER_SUPER, AUDIT_$SUSPEND
 *                          unless bit 0, optional ACL_$DOWN
 *   0x00E58352-0x00E58392  restore the saved SIDs, an empty project list,
 *                          AUDIT_$RESUME, ACL_$EXIT_SUPER
 *
 * Quirks reproduced:
 *   - The version checks are signed word compares (`bge`).
 *   - Failures to restore the identity are ignored (scratch status).
 */

#include "dir/dir_internal.h"
#include "acl/acl.h"
#include "audit/audit.h"
#include "uid/uid.h"

/* `move.w #0x14,(A0)` 0x00E58220 */
#define DIR_SERVER_REPLY_LEN        0x14

/* The highest request header version (`moveq #0x1,D1` 0x00E58230) */
#define DIR_SERVER_HDR_VERSION      1

/* DIR_$DO_OP sizes, `move.l #0x292011a,-(SP)` 0x00E5831E */
#define DIR_SERVER_REQ_SIZE         0x0292
#define DIR_SERVER_RESP_SIZE        0x011A

/*
 * `pea (0x28,PC)` at 0x00E58374 = 0x00E5839E, bytes 00 00: the project
 * list count for the restore.
 */
static const int16_t dir_$server_zero_count = 0;

void DIR_$SERVER(void *request, void *response, uint16_t *reply_len)
{
    dir_$server_request_t *req = (dir_$server_request_t *)request;   /* A2 */
    dir_$server_reply_t *rep = (dir_$server_reply_t *)response;      /* A3 */
    status_$t scratch;                                              /* (-0x04,A6) */
    int16_t body_version;

    /* 0x00E5821A-0x00E58226 */
    rep->long_08 = 0;
    *reply_len = DIR_SERVER_REPLY_LEN;
    rep->word_12 = 0;

    /* 0x00E58228-0x00E58244 */
    if (req->hdr_version > DIR_SERVER_HDR_VERSION) {
        rep->version = DIR_SERVER_HDR_VERSION;
        rep->status = status_$naming_bad_request_header_version;
        return;
    }

    /* 0x00E58248-0x00E5826E */
    body_version = (int16_t)DIR_$OP_REC(req->op >> 1).version;
    if (body_version < req->version) {
        rep->version = (uint16_t)body_version;
        rep->status = status_$naming_bad_request_body_version;
        return;
    }

    /* 0x00E58272-0x00E58282 */
    if (req->hdr_version == 0) {
        req->cur_proj[0] = DIR_SERVER.default_proj[0];
        req->cur_proj[1] = DIR_SERVER.default_proj[1];
        req->cur_proj[2] = DIR_SERVER.default_proj[2];
    }

    /* 0x00E58284-0x00E582A8 */
    if (DIR_SERVER.first_time < 0) {
        ACL_$GET_RE_ALL_SIDS(DIR_SERVER.saved_acl, DIR_SERVER.saved_re_sids,
                             DIR_SERVER.saved_prot, DIR_SERVER.saved_subsys,
                             &scratch);
        DIR_SERVER.first_time = 0;
    }

    /* 0x00E582AC-0x00E582F6 */
    ACL_$ENTER_SUPER();
    AUDIT_$SUSPEND();
    ACL_$SET_RE_ALL_SIDS(DIR_SERVER.saved_acl, req->re_sids,
                         DIR_SERVER.saved_prot, req->cur_proj, &rep->status);
    if (rep->status == status_$ok) {
        ACL_$SET_PROJ_LIST(req->proj_list, &req->proj_count, &rep->status);
        if (rep->status == status_$ok) {
            /* 0x00E582F8-0x00E58314 */
            if ((req->flags & DIR_SERVER_REQ_SUBSYS_UP) != 0) {
                ACL_$UP();
            }
            if ((req->flags & DIR_SERVER_REQ_KEEP_AUDIT) == 0) {
                AUDIT_$RESUME();
            }
            ACL_$EXIT_SUPER();

            /* 0x00E5831A-0x00E5832C */
            DIR_$DO_OP(request, DIR_SERVER_REQ_SIZE, DIR_SERVER_RESP_SIZE,
                       response, reply_len);

            /* 0x00E58330-0x00E58350 */
            ACL_$ENTER_SUPER();
            if ((req->flags & DIR_SERVER_REQ_KEEP_AUDIT) == 0) {
                AUDIT_$SUSPEND();
            }
            if ((req->flags & DIR_SERVER_REQ_SUBSYS_UP) != 0) {
                ACL_$DOWN();
            }
        }
    }

    /* 0x00E58352-0x00E58392 */
    ACL_$SET_RE_ALL_SIDS(DIR_SERVER.saved_acl, DIR_SERVER.saved_re_sids,
                         DIR_SERVER.saved_prot, DIR_SERVER.saved_subsys,
                         &scratch);
    ACL_$SET_PROJ_LIST(&UID_$NIL, (int16_t *)&dir_$server_zero_count, &scratch);
    AUDIT_$RESUME();
    ACL_$EXIT_SUPER();
}
